Exercise 2 — if / elif / else
Starting with a = 3, build up a conditional statement step by step:

Write an if/else block that prints "a is positive" when a &gt; 0 and "a is negative" otherwise.
Add an elif branch so that "a is zero" is printed when a == 0.
Test your code with a = 0, a = 5, and a = -3 by changing the first line.

#| '!! shinylive warning !!': |
#|   shinylive does not work in self-contained HTML documents.
#|   Please set `embed-resources: false` in your metadata.
#| standalone: true
#| viewerHeight: 240
from shiny import App, ui, render, reactive
import io, contextlib, ast

app_ui = ui.page_fluid(
    ui.input_text_area("code", None, value="a = 3\n", width='100%', height='130px'),
    ui.input_action_button("run", "Run Code", class_="btn-success"),
    ui.output_text_verbatim("out")
)
def server(input, output, session):
    @render.text
    @reactive.event(input.run)
    async def out():
        f = io.StringIO(); ns = {}
        with contextlib.redirect_stdout(f):
            try:
                tree = ast.parse(input.code())
                for node in tree.body:
                    if isinstance(node, ast.Expr):
                        val = eval(compile(ast.Expression(node.value),'&lt;s&gt;','eval'), ns)
                        if val is not None: print(val)
                    else: exec(compile(ast.Module([node],[]),'&lt;s&gt;','exec'), ns)
            except Exception as e: print(f"Error: {e}")
        return f.getvalue()
app = App(app_ui, server)
